using System; using System.Data; using System.Text; using System.Web; using System.Web.UI; using HospitalMSWebApp.Infrastructure; using HospitalMSWebApp.Services;
namespace HospitalMSWebApp.Views.Nurse {
 public class Workspace:AppPage { readonly Database db=new Database(); readonly HospitalWorkflowService wf=new HospitalWorkflowService(); string csrf;
  protected void Page_Load(object s,EventArgs e){if(!RequireRoles("Nurse"))return;csrf=Convert.ToString(Session["NurseCsrf"]);if(string.IsNullOrEmpty(csrf)){csrf=Guid.NewGuid().ToString("N");Session["NurseCsrf"]=csrf;}if(Request.HttpMethod=="POST")Save();}
  void Save(){if(Request.Form["csrf"]!=csrf){Go("Security validation failed.",true);return;}try{Session["NurseCsrf"]=Guid.NewGuid().ToString("N");int patient=I("patientId");if(patient<1)throw new ArgumentException("Select an admitted patient.");long id=wf.RecordNursingNote(patient,L("admissionId"),CurrentUser.UserId,V("careStatus"),V("note"),D("temperature"),IN("pulse"),IN("systolic"),IN("diastolic"));AuditService.Write(CurrentUser,"NursingNoteRecorded","NursingNote",id.ToString(),"Nursing assessment and vital signs recorded",Request);Go("Nursing assessment saved.",false);}catch(Exception x){Go(x is ArgumentException||x is InvalidOperationException?x.Message:"Assessment could not be saved.",true);}}
  protected override void Render(HtmlTextWriter w){ if(Response.IsRequestBeingRedirected || CurrentUser==null)return;int patient;int.TryParse(Request.QueryString["patientId"],out patient);var b=new StringBuilder(GuardianUi.Begin(CurrentUser,"Nurse workspace",Request.Path));Notice(b);b.Append("<div class='row'>").Append(GuardianUi.Stat("Admitted patients",db.Scalar("SELECT COUNT(*) FROM gh.Admissions WHERE DischargedAt IS NULL"))).Append(GuardianUi.Stat("Triage waiting",db.Scalar("SELECT COUNT(*) FROM gh.TriageAssessments WHERE Status='Waiting'"))).Append(GuardianUi.Stat("Assessments today",db.Scalar("SELECT COUNT(*) FROM gh.NursingNotes WHERE CAST(RecordedAt AS date)=CAST(SYSUTCDATETIME() AS date)"))).Append(GuardianUi.Stat("Beds ready",db.Scalar("SELECT COUNT(*) FROM gh.Beds WHERE Status='Available'"))).Append("</div>");b.Append("<section class='panel'><h2>Admitted patients</h2>").Append(GuardianUi.Table(db.Query(@"SELECT a.AdmissionId AS [Admission],p.patientId AS [Patient ID],p.MedicalRecordNumber AS [MRN],p.patientName AS [Patient],w.WardName AS [Ward],r.RoomNumber AS [Room],b.BedNumber AS [Bed],a.Status,p.patientAllergies AS [Allergies] FROM gh.Admissions a JOIN dbo.patientTbl p ON p.patientId=a.PatientId LEFT JOIN gh.Beds b ON b.BedId=a.BedId LEFT JOIN gh.Rooms r ON r.RoomId=b.RoomId LEFT JOIN gh.Wards w ON w.WardId=r.WardId WHERE a.DischargedAt IS NULL ORDER BY a.AdmittedAt DESC"),"Patient ID","Workspace.aspx?patientId=","Open assessment","#nursing-assessment")).Append("</section>");b.Append("<section class='panel'><h2>Patient record</h2><form method='get' class='form-grid'>").Append(O("Admitted patient","patientId","SELECT DISTINCT p.patientId AS Id,p.patientName AS Name FROM gh.Admissions a JOIN dbo.patientTbl p ON p.patientId=a.PatientId WHERE a.DischargedAt IS NULL",true)).Append("<button>Open record</button></form></section>");if(patient>0){b.Append(History(patient));b.Append("<section class='panel'><h2>Vital signs history</h2>").Append(Table(db.Query("SELECT TOP 50 v.RecordedAt,v.TemperatureC,v.Pulse,v.SystolicBp,v.DiastolicBp FROM gh.VitalSigns v LEFT JOIN gh.Encounters e ON e.EncounterId=v.EncounterId WHERE v.PatientId=@P OR e.PatientId=@P ORDER BY v.RecordedAt DESC",Database.Parameter("@P",patient)))).Append("</section><section class='panel'><h2>Patient timeline</h2>").Append(Table(db.Query("SELECT TOP 50 EventAt,EventType,Detail FROM gh.vwPatientTimeline WHERE PatientId=@P ORDER BY EventAt DESC",Database.Parameter("@P",patient)))).Append("</section>");}b.Append(RenderAssessmentForm()).Append(GuardianUi.End());w.Write(b.ToString());}
  string History(int p){
   return GuardianUi.PatientSummary(db.Query("SELECT p.MedicalRecordNumber AS MRN,p.patientName AS Patient,p.patientDOB AS BirthDate,p.patientAllergies AS Allergies,pp.BloodType,pp.ChronicConditions FROM dbo.patientTbl p LEFT JOIN gh.PatientProfiles pp ON pp.PatientId=p.patientId WHERE p.patientId=@P",Database.Parameter("@P",p)))
    +GuardianUi.Panel("Nursing history",Table(db.Query("SELECT TOP 25 CareStatus AS Status,Note,RecordedAt AS Recorded FROM gh.NursingNotes WHERE PatientId=@P ORDER BY RecordedAt DESC",Database.Parameter("@P",p))));
  }
  string RenderAssessmentForm(){
   int patient;if(!int.TryParse(Request.QueryString["patientId"],out patient)||patient<1)return GuardianUi.Panel("Nursing assessment","<p>Open an admitted patient from the worklist to review their context and record an assessment.</p>");
   var records=db.Query(@"SELECT a.AdmissionId,p.patientName,p.MedicalRecordNumber,w.WardName,r.RoomNumber,b.BedNumber,
       n.CareStatus,n.RecordedAt,u.DisplayName AS RecordedBy FROM gh.Admissions a JOIN dbo.patientTbl p ON p.patientId=a.PatientId
       LEFT JOIN gh.Beds b ON b.BedId=a.BedId LEFT JOIN gh.Rooms r ON r.RoomId=b.RoomId LEFT JOIN gh.Wards w ON w.WardId=r.WardId
       OUTER APPLY(SELECT TOP 1 CareStatus,RecordedAt,RecordedByUserId FROM gh.NursingNotes WHERE AdmissionId=a.AdmissionId ORDER BY RecordedAt DESC,NursingNoteId DESC)n
       LEFT JOIN gh.UserAccounts u ON u.UserId=n.RecordedByUserId WHERE a.PatientId=@P AND a.DischargedAt IS NULL",Database.Parameter("@P",patient));
   if(records.Rows.Count!=1)return GuardianUi.Panel("Nursing assessment","<p>No active admission is available for this patient. Refresh the admitted worklist. Historical records remain available.</p>");
   var row=records.Rows[0];
   string context="<p><strong>"+H(Convert.ToString(row["patientName"]))+" · "+H(Convert.ToString(row["MedicalRecordNumber"]))+"</strong></p><p>"+H(Convert.ToString(row["WardName"])+" / "+Convert.ToString(row["RoomNumber"])+" / "+Convert.ToString(row["BedNumber"]))+"</p>";
   context+=row["RecordedAt"]==DBNull.Value?"<p>No assessment recorded for this admission.</p>":"<p>Latest recorded care status: "+GuardianUi.Badge(Convert.ToString(row["CareStatus"]))+" · "+H(Convert.ToString(row["RecordedBy"]))+" · "+Convert.ToDateTime(row["RecordedAt"]).ToString("dd MMM yyyy HH:mm")+" UTC. This is the last recorded assessment, not a new clinical evaluation.</p>";
   return GuardianUi.Panel("Nursing assessment",context+"<form method='post' class='form-grid three'><input type='hidden' name='csrf' value='"+H(csrf)+"'><input type='hidden' name='patientId' value='"+patient+"'><input type='hidden' name='admissionId' value='"+row["AdmissionId"]+"'>"+O("Care status","careStatus","SELECT 'Stable' AS Id,'Stable' AS Name UNION ALL SELECT 'NeedsReview','Needs review' UNION ALL SELECT 'Escalated','Escalated' UNION ALL SELECT 'DischargeReady','Discharge ready'",true)+In("Temperature °C","temperature","number")+In("Pulse","pulse","number")+In("Systolic BP","systolic","number")+In("Diastolic BP","diastolic","number")+"<label class='gh-wide-field'>Nursing note<textarea name='note' required></textarea></label><p>Recording Discharge ready informs the care team; it does not discharge the patient or free the bed.</p><button>Save assessment</button></form>");
  }
  string O(string l,string n,string q,bool r){var t=db.Query(q);var b=new StringBuilder("<label>"+H(l)+"<select name='"+n+"'"+(r?" required":"")+"><option value=''>Select</option>");foreach(DataRow x in t.Rows)b.Append("<option value='").Append(H(Convert.ToString(x["Id"]))).Append(n=="patientId"&&Convert.ToString(x["Id"])==Request.QueryString["patientId"]?"' selected>":"'>").Append(H(Convert.ToString(x["Name"]))).Append("</option>");return b.Append("</select></label>").ToString();} static string In(string l,string n,string t){return "<label>"+l+"<input name='"+n+"' type='"+t+"'"+(t=="number"?" step='any'":"")+"></label>";} static string H(string s){return HttpUtility.HtmlEncode(s??"");} static string Table(DataTable t){return GuardianUi.Table(t);}string V(string k){return(Request.Form[k]??"").Trim();}int I(string k){return IN(k).GetValueOrDefault();}int? IN(string k){int x;if(V(k)=="")return null;if(!int.TryParse(V(k),out x))throw new ArgumentException("Enter a valid "+k+".");return x;}long? L(string k){long x;if(V(k)=="")return null;if(!long.TryParse(V(k),out x))throw new ArgumentException("Select a valid "+k+".");return x;}decimal? D(string k){decimal x;if(V(k)=="")return null;if(!decimal.TryParse(V(k),System.Globalization.NumberStyles.Number,System.Globalization.CultureInfo.InvariantCulture,out x))throw new ArgumentException("Enter a valid "+k+".");return x;}void Notice(StringBuilder b){var n=Request.QueryString["notice"];var e=Request.QueryString["error"];if(!string.IsNullOrEmpty(n))b.Append("<div class='notice success'>✓ ").Append(H(n)).Append("</div>");if(!string.IsNullOrEmpty(e))b.Append("<div class='notice error'>! ").Append(H(e)).Append("</div>");}void Go(string m,bool e){int selected;int.TryParse(Request.Form["patientId"],out selected);Response.Redirect("Workspace.aspx?patientId="+selected+"&"+(e?"error":"notice")+"="+HttpUtility.UrlEncode(m)+"#nursing-assessment",false);Context.ApplicationInstance.CompleteRequest();}
 }
}
